SourceCode.Declaration:
/// <summary>
/// getOpportunityCount's answer. Eligible false means show nothing. When true, the server has
/// created (or found) a one-line journal for this spot and returns it - counted blind, DIRECT mode.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountOpportunityResponse
{
    boolean                       success;
    str                           errorCode;
    boolean                       eligible;
    str                           journalId;
    str                           journalNameId;
    str                           description;
    HSMobileOpsCountDirectLineRow line;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Eligible')]
public boolean parmEligible(boolean _value = eligible)
{
    eligible = _value;
    return eligible;
}

[DataMemberAttribute('JournalId')]
public str parmJournalId(str _value = journalId)
{
    journalId = _value;
    return journalId;
}

[DataMemberAttribute('JournalNameId')]
public str parmJournalNameId(str _value = journalNameId)
{
    journalNameId = _value;
    return journalNameId;
}

[DataMemberAttribute('Description')]
public str parmDescription(str _value = description)
{
    description = _value;
    return description;
}

[DataMemberAttribute('Line')]
public HSMobileOpsCountDirectLineRow parmLine(HSMobileOpsCountDirectLineRow _value = line)
{
    line = _value;
    return line;
}
